<div class="lab-widget">
  <canvas id="stage" width="680" height="380"></canvas>
  <div class="controls-row">
    <div class="ctrl-group">
      <label for="noiseAmp">噪声幅度</label>
      <input type="range" id="noiseAmp" min="0" max="0.5" step="0.01" value="0.2">
      <span class="val mono" id="noiseAmpVal">0.20</span>
    </div>
    <div class="ctrl-group">
      <label for="stepSize">步长</label>
      <input type="range" id="stepSize" min="0.01" max="0.5" step="0.01" value="0.1">
      <span class="val mono" id="stepSizeVal">0.10</span>
    </div>
    <div class="btn-group">
      <button id="toggleNoise" class="accent">关噪声</button>
      <button id="resetBtn">重置</button>
    </div>
  </div>
  <div class="readout-row">
    <span>参数位置: <span class="mono" id="posReadout">(-2.50, 2.00)</span></span>
    <span>轨迹步数: <span class="mono" id="stepReadout">5</span></span>
    <span style="display:flex;align-items:center;gap:6px;">
      <span style="display:inline-block;width:14px;height:2px;background:var(--accent);border-radius:1px;"></span> 有噪声
      <span style="display:inline-block;width:14px;height:2px;border-top:2px dashed var(--text2);margin-left:8px;"></span> 无噪声
    </span>
  </div>
</div>
<script>
  (function() {
    const root = document.documentElement;
    const tok = (n) => getComputedStyle(root).getPropertyValue(n).trim();
    const canvas = document.getElementById('stage');
    const ctx = canvas.getContext('2d');
    const W = 680, H = 380;

    // state
    let noiseAmplitude = 0.2;
    let stepSize = 0.1;
    let paramX = -2.5;
    let paramY = 2.0;
    let trajectory = [{x: paramX, y: paramY}];
    let running = true;
    let noiseEnabled = true;
    let savedNoiseAmp = 0.2; // for toggle

    // 无噪声对比轨迹 (从同一起点)
    let noiselessTrajectory = [{x: -2.5, y: 2.0}];
    let noiselessX = -2.5, noiselessY = 2.0;

    // DOM refs
    const noiseAmpInput = document.getElementById('noiseAmp');
    const noiseAmpVal = document.getElementById('noiseAmpVal');
    const stepSizeInput = document.getElementById('stepSize');
    const stepSizeVal = document.getElementById('stepSizeVal');
    const posReadout = document.getElementById('posReadout');
    const stepReadout = document.getElementById('stepReadout');
    const toggleBtn = document.getElementById('toggleNoise');
    const resetBtn = document.getElementById('resetBtn');

    // 损失函数: 两个局部极小 (一个全局极小在 (1.2, -0.8) 附近)
    function lossGrad(x, y) {
      // 设计曲面: 全局极小在 (1.2, -0.8), 局部极小在 (-1.0, 1.2), 另一个局部极小在 (2.0, 1.5)
      // 梯度 = 各高斯峰负梯度之和 + 一个碗状
      // 用可微形式: f = 0.5*((x-1.2)^2 + (y+0.8)^2) - 1.2*exp(-((x+1)^2+(y-1.2)^2)/0.6) - 0.8*exp(-((x-2)^2+(y-1.5)^2)/0.5)
      // 梯度分量:
      const dx_global = (x - 1.2);
      const dy_global = (y + 0.8);
      const g1 = Math.exp(-((x+1)*(x+1)+(y-1.2)*(y-1.2))/0.6);
      const g2 = Math.exp(-((x-2)*(x-2)+(y-1.5)*(y-1.5))/0.5);
      const dx = dx_global + 1.2 * g1 * (2*(x+1)/0.6) + 0.8 * g2 * (2*(x-2)/0.5);
      const dy = dy_global + 1.2 * g1 * (2*(y-1.2)/0.6) + 0.8 * g2 * (2*(y-1.5)/0.5);
      return { dx, dy };
    }

    function lossVal(x, y) {
      const global = 0.5*((x-1.2)*(x-1.2)+(y+0.8)*(y+0.8));
      const bump1 = -1.2 * Math.exp(-((x+1)*(x+1)+(y-1.2)*(y-1.2))/0.6);
      const bump2 = -0.8 * Math.exp(-((x-2)*(x-2)+(y-1.5)*(y-1.5))/0.5);
      return global + bump1 + bump2;
    }

    // 重置 (保留噪声开关状态)
    function resetState() {
      paramX = -2.5;
      paramY = 2.0;
      trajectory = [{x: paramX, y: paramY}];
      noiselessX = -2.5;
      noiselessY = 2.0;
      noiselessTrajectory = [{x: -2.5, y: 2.0}];
      running = true;
      updateReadouts();
    }

    // 重置并重新开始 (用于滑块变化)
    function resetAndRestart() {
      resetState();
      // 立即走几步让首帧有轨迹
      for (let i = 0; i < 5; i++) {
        stepOnce();
      }
      draw();
    }

    // 单步更新 (有噪声 + 无噪声对比)
    function stepOnce() {
      if (!running) return;

      // 有噪声步
      const g = lossGrad(paramX, paramY);
      let nx = 0, ny = 0;
      if (noiseEnabled && noiseAmplitude > 0) {
        nx = (Math.random() - 0.5) * 2 * noiseAmplitude;
        ny = (Math.random() - 0.5) * 2 * noiseAmplitude;
      }
      paramX = paramX - stepSize * g.dx + nx;
      paramY = paramY - stepSize * g.dy + ny;
      // 边界钳位
      paramX = Math.min(3, Math.max(-3, paramX));
      paramY = Math.min(3, Math.max(-3, paramY));
      trajectory.push({x: paramX, y: paramY});

      // 无噪声对比步 (从独立状态)
      const g2 = lossGrad(noiselessX, noiselessY);
      noiselessX = noiselessX - stepSize * g2.dx;
      noiselessY = noiselessY - stepSize * g2.dy;
      noiselessX = Math.min(3, Math.max(-3, noiselessX));
      noiselessY = Math.min(3, Math.max(-3, noiselessY));
      noiselessTrajectory.push({x: noiselessX, y: noiselessY});
    }

    // 绘制
    function draw() {
      const ink = tok('--ink');
      const accent = tok('--accent');
      const line = tok('--line');
      const mute = tok('--text2');
      const bg = tok('--bg');
      const card = tok('--card');

      ctx.clearRect(0, 0, W, H);

      // 背景
      ctx.fillStyle = card;
      ctx.fillRect(0, 0, W, H);

      // 坐标映射: x: -3..3 → 60..620, y: -3..3 → 340..40 (y翻转)
      const mapX = (x) => 60 + (x + 3) / 6 * 560;
      const mapY = (y) => 340 - (y + 3) / 6 * 300;

      // 绘制等高线 (损失函数)
      const levels = [0.2, 0.5, 1.0, 1.8, 3.0, 5.0, 8.0];
      ctx.strokeStyle = line;
      ctx.lineWidth = 0.8;
      ctx.globalAlpha = 0.5;
      for (let lv of levels) {
        ctx.beginPath();
        let started = false;
        // 采样网格
        const step = 0.08;
        for (let px = -3; px <= 3; px += step) {
          for (let py = -3; py <= 3; py += step) {
            const v = lossVal(px, py);
            if (Math.abs(v - lv) < 0.15) {
              const sx = mapX(px), sy = mapY(py);
              if (!started) { ctx.moveTo(sx, sy); started = true; }
              else { ctx.lineTo(sx, sy); }
            }
          }
        }
        ctx.stroke();
      }
      ctx.globalAlpha = 1.0;

      // 标注极小点 (示意)
      ctx.fillStyle = mute;
      ctx.font = '10px ' + tok('--mono');
      ctx.fillText('全局极小', mapX(1.2)-20, mapY(-0.8)-8);
      ctx.fillText('局部极小', mapX(-1.0)-20, mapY(1.2)-8);
      ctx.fillText('局部极小', mapX(2.0)-20, mapY(1.5)-8);

      // 绘制无噪声轨迹 (虚线)
      ctx.strokeStyle = mute;
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 4]);
      ctx.beginPath();
      if (noiselessTrajectory.length > 0) {
        const p0 = noiselessTrajectory[0];
        ctx.moveTo(mapX(p0.x), mapY(p0.y));
        for (let i = 1; i < noiselessTrajectory.length; i++) {
          ctx.lineTo(mapX(noiselessTrajectory[i].x), mapY(noiselessTrajectory[i].y));
        }
      }
      ctx.stroke();
      ctx.setLineDash([]);

      // 绘制有噪声轨迹 (实线, 微光)
      const dark = root.getAttribute('data-theme') === 'lab' || root.getAttribute('data-theme') === 'cobalt-grid';
      if (dark && trajectory.length > 1) {
        ctx.shadowColor = accent;
        ctx.shadowBlur = 8;
      }
      ctx.strokeStyle = accent;
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      if (trajectory.length > 0) {
        const p0 = trajectory[0];
        ctx.moveTo(mapX(p0.x), mapY(p0.y));
        for (let i = 1; i < trajectory.length; i++) {
          ctx.lineTo(mapX(trajectory[i].x), mapY(trajectory[i].y));
        }
      }
